import json
import os
import re
import subprocess
_SCRIPT = '/opt/billing/jobs/renew_subscriptions.py'
_PLAN_DIR = '/opt/billing/config/plans'
_DATE_RE = re.compile('^\\d{4}-\\d{2}-\\d{2}$')
_PLAN_RE = re.compile('^[a-z0-9_\\-]{2,40}$')

def _load_plan_config(plan_code):
    path = os.path.join(_PLAN_DIR, plan_code + '.json')
    try:
        with open(path, 'r', encoding='utf-8') as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return None

def run_renewal_batch(plan_code, billing_date, dry_run=True):
    if not _PLAN_RE.match(plan_code):
        return {'ok': False, 'error': 'invalid plan_code'}
    if not _DATE_RE.match(billing_date):
        return {'ok': False, 'error': 'billing_date must be YYYY-MM-DD'}
    plan_config = _load_plan_config(plan_code)
    cmd = ['python3', _SCRIPT, '--plan', plan_code, '--date', billing_date]
    if dry_run:
        cmd.append('--dry-run')
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=900, check=False)
    except subprocess.TimeoutExpired:
        return {'ok': False, 'error': 'renewal job timed out', 'command': cmd}
    return {'ok': proc.returncode == 0, 'exit_code': proc.returncode, 'dry_run': dry_run, 'command': cmd, 'plan_config': plan_config, 'stdout': proc.stdout[-4000:], 'stderr': proc.stderr[-2000:]}
